"""Open-source voice, ambience and music backend for tests (VOICE_BACKEND=local).

NOT for production, and ENGLISH ONLY. Stands in for ElevenLabs while no key is available.
- Speech: Meta MMS-TTS (facebook/mms-tts-eng, VITS, CC-BY-NC 4.0) on CPU. One base voice.
- "Voice design": there is no model that designs a voice from a description, so each voice is the base
  voice with a pitch shift and a tempo change derived from keywords in the description (male / female,
  deep / high, old / young, slow / fast). The voice id carries the parameters: `local:<semitones>:<tempo>`.
- No emotion control: audio tags such as [angry] are stripped before synthesis.
- No word timings: alignment is None, so captions fall back to even spacing (the guide's own fallback).
- Ambience and music are procedural (filtered noise, soft chords made with ffmpeg), not generated by a model.
"""
from __future__ import annotations

import hashlib
import io
import re
import subprocess
import threading
import wave

import numpy as np

from app.jobs.errors import PermanentError

MODEL_ID = "facebook/mms-tts-eng"
VOICE_RE = re.compile(r"^local:(-?\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$")
DEFAULT_SAMPLE = "I know what you did, and I will not stay silent any longer."
_lock = threading.Lock()
_model: tuple | None = None


def make_voice_id(semitones: float, tempo: float) -> str:
    return f"local:{semitones:.1f}:{tempo:.2f}"


def parse_voice_id(voice_id: str) -> tuple[float, float]:
    m = VOICE_RE.match(voice_id or "")
    if not m:
        raise PermanentError(f"{voice_id!r} is not a local voice id (expected local:<semitones>:<tempo>)")
    return float(m.group(1)), float(m.group(2))


def voice_params(description: str, variant: int = 0) -> tuple[float, float]:
    """(semitones, tempo) from the description's keywords; `variant` spreads the candidates a little."""
    d = description.lower()
    semis, tempo = 0.0, 1.0
    if re.search(r"\b(male|man|boy|father|husband|gentleman)\b", d) and not re.search(r"\b(female|woman|girl|mother|wife|lady)\b", d):
        semis -= 3.5
    elif re.search(r"\b(female|woman|girl|mother|wife|lady)\b", d):
        semis += 1.0
    if re.search(r"\b(deep|low|gravelly|bass|baritone)\b", d):
        semis -= 2.0
    if re.search(r"\b(high|bright|light|soprano)\b", d):
        semis += 2.0
    if re.search(r"\b(young|teen|youthful)\b", d):
        semis += 1.0
    if re.search(r"\b(old|elderly|aged|mature)\b", d):
        semis -= 1.0
        tempo *= 0.93
    if re.search(r"\b(slow|measured|calm|deliberate)\b", d):
        tempo *= 0.93
    if re.search(r"\b(fast|brisk|quick|energetic)\b", d):
        tempo *= 1.08
    semis += (-1.0, 0.0, 1.0)[variant % 3] * 0.8
    return max(-8.0, min(8.0, semis)), max(0.8, min(1.2, tempo))


def strip_tags(text: str) -> str:
    return re.sub(r"\[[^\]]*\]", " ", text).strip()


def _load():
    global _model
    with _lock:
        if _model is None:
            from transformers import AutoTokenizer, VitsModel

            _model = (AutoTokenizer.from_pretrained(MODEL_ID), VitsModel.from_pretrained(MODEL_ID).eval())
        return _model


def _wav_bytes(samples: np.ndarray, rate: int) -> bytes:
    buf = io.BytesIO()
    with wave.open(buf, "wb") as f:
        f.setnchannels(1)
        f.setsampwidth(2)
        f.setframerate(rate)
        f.writeframes((np.clip(samples, -1, 1) * 32767).astype(np.int16).tobytes())
    return buf.getvalue()


def _ffmpeg(args: list[str], data: bytes | None = None) -> bytes:
    run = subprocess.run(["ffmpeg", "-v", "error", "-y", *args], input=data, capture_output=True)
    if run.returncode != 0:
        raise PermanentError("ffmpeg failed: " + run.stderr.decode(errors="replace")[:300])
    return run.stdout


def _to_mp3(wav: bytes, semitones: float, tempo: float) -> bytes:
    """Pitch-shift and re-time with rubberband, resample to 44.1 kHz mono, encode MP3 at 128 kbps."""
    flt = f"rubberband=pitch={2 ** (semitones / 12):.5f}:tempo={tempo:.4f}" if (semitones or tempo != 1.0) else "anull"
    return _ffmpeg(["-f", "wav", "-i", "pipe:0", "-af", flt, "-ar", "44100", "-ac", "1", "-b:a", "128k", "-f", "mp3", "pipe:1"], wav)


def speech(text: str, voice_id: str, language_code: str, seed: int) -> bytes:
    """MP3 bytes for one line. Raises PermanentError for a language other than English."""
    import torch

    if language_code != "en":
        raise PermanentError("the local test voice backend is English-only; use an English series or set ELEVENLABS_API_KEY")
    semitones, tempo = parse_voice_id(voice_id)
    clean = strip_tags(text)
    if not clean:
        raise PermanentError("nothing to say: the line is empty after removing audio tags")
    tok, model = _load()
    with _lock, torch.no_grad():
        torch.manual_seed(seed % (2**31))
        wave_out = model(**tok(clean, return_tensors="pt")).waveform[0].numpy()
    return _to_mp3(_wav_bytes(wave_out, model.config.sampling_rate), semitones, tempo)


def design(description: str, sample_text: str | None = None, count: int = 3) -> list[dict]:
    """Candidate voices from a description: [{generated_voice_id, audio, duration_secs}]."""
    out = []
    for i in range(count):
        voice_id = make_voice_id(*voice_params(description, i))
        audio = speech(sample_text or DEFAULT_SAMPLE, voice_id, "en", int(hashlib.sha256(description.encode()).hexdigest()[:6], 16) + i)
        out.append({"generated_voice_id": voice_id, "audio": audio, "duration_secs": None})
    return out


def ambience(text: str, duration_seconds: float, loop: bool = True) -> bytes:
    """Procedural room-tone / ambience: filtered pink noise whose colour depends on the description."""
    h = int(hashlib.sha256(text.encode()).hexdigest()[:4], 16)
    cutoff = 600 + h % 2400
    d = max(0.5, float(duration_seconds))
    return _ffmpeg([
        "-f", "lavfi", "-i", f"anoisesrc=d={d}:c=pink:a=0.25:seed={h}", "-af", f"lowpass=f={cutoff},highpass=f=60,tremolo=f=0.2:d=0.2,afade=t=in:d=0.3,afade=t=out:st={max(d - 0.3, 0):.2f}:d=0.3",
        "-ar", "44100", "-ac", "1", "-b:a", "96k", "-f", "mp3", "pipe:1"])


def music(prompt: str, length_ms: int) -> bytes:
    """Procedural underscore: a slow minor-chord pad with a soft pulse. Not a generated composition."""
    d = max(3.0, length_ms / 1000)
    h = int(hashlib.sha256(prompt.encode()).hexdigest()[:4], 16)
    root = 110 * 2 ** ((h % 7) / 12)
    expr = "+".join(f"{a}*sin(2*PI*{root * r:.2f}*t)" for a, r in ((0.12, 1), (0.09, 1.1892), (0.09, 1.4983), (0.05, 2)))
    return _ffmpeg(["-f", "lavfi", "-i", f"aevalsrc='({expr})*(0.7+0.3*sin(2*PI*0.25*t))':d={d}:s=44100", "-af", f"lowpass=f=1800,afade=t=in:d=1.5,afade=t=out:st={max(d - 1.5, 0):.2f}:d=1.5",
                    "-ac", "2", "-b:a", "128k", "-f", "mp3", "pipe:1"])
